{"issue": true, "summary": "In `handleError`, when `errorHandler.func` throws, the code calls `reply.send(err)` which may trigger another error handler cycle, but the `nextErrorHandler` is set to the prototype of the current handler, potentially causing infinite recursion or incorrect error handling flow.", "edits": [{"path": "lib/error-handler.js", "old": "  // In case the error handler throws, we set the next errorHandler so we can error again
  reply[kReplyNextErrorHandler] = Object.getPrototypeOf(errorHandler)

  // we need to remove content-type to allow content-type guessing for serialization
  delete reply[kReplyHeaders]['content-type']
  delete reply[kReplyHeaders]['content-length']

  const func = errorHandler.func

  if (!func) {
    reply[kReplyNextErrorHandler] = false
    fallbackErrorHandler(error, reply, cb)
    return
  }

  try {
    const result = func(error, reply.request, reply)
    if (result !== undefined) {
      if (result !== null && typeof result.then === 'function') {
        const store = reply[kDiagnosticsStore] || null
        wrapThenable(result, reply, store)
      } else {
        reply.send(result)
      }
    }
  } catch (err) {
    reply.send(err)
  }", "new": "  // In case the error handler throws, we set the next errorHandler so we can error again
  reply[kReplyNextErrorHandler] = Object.getPrototypeOf(errorHandler)

  // we need to remove content-type to allow content-type guessing for serialization
  delete reply[kReplyHeaders]['content-type']
  delete reply[kReplyHeaders]['content-length']

  const func = errorHandler.func

  if (!func) {
    reply[kReplyNextErrorHandler] = false
    fallbackErrorHandler(error, reply, cb)
    return
  }

  try {
    const result = func(error, reply.request, reply)
    if (result !== undefined) {
      if (result !== null && typeof result.then === 'function') {
        const store = reply[kDiagnosticsStore] || null
        wrapThenable(result, reply, store)
      } else {
        reply.send(result)
      }
    }
  } catch (err) {
    // Prevent infinite recursion by setting nextErrorHandler to false
    reply[kReplyNextErrorHandler] = false
    reply.send(err)
  }"}]}
